# evaluate common local boolean rule radius 1 across all row transition examples, with cyclic indexing
import itertools
for rad in [0,1,2]:
 ctx=[]; vals=[]
 for a,b in rows:
  a=[int(bool(x)) for x in a]; b=[int(bool(x)) for x in b]
  for j,y in enumerate(b):
   tup=tuple(a[(j+d)%5] for d in range(-rad,rad+1))
   ctx.append(tup); vals.append(y)
 tt={}
 conf=True
 for x,y in zip(ctx,vals):
  if x in tt and tt[x]!=y: conf=False
  tt[x]=y
 print(rad,conf,len(tt),tt if conf else '')

